}

function addImageContain(slide, img, x, y, w, h) {
  slide.addShape(S.roundRect, { x, y, w, h, rectRadius: 0.08, fill: { color: C.white }, line: { color: C.line, width: 0.7 } });
  slide.addImage({ path: img, x: x+0.08, y: y+0.08, w: w-0.16, h: h-0.16, sizing: { type: 'contain', x: x+0.08, y: y+0.08, w: w-0.16, h: h-0.16 } });
}

function addMetric(slide, value, label, x, y, w, accent=C.teal) {
  card(slide, x, y, w, 0.95, C.white);
